return [{ json: {
  reply: 'That message is a bit long — could you give me the short version?',
  stage: null, state: null, session_id: $json.sessionId, employee_code: '',
  timed_out: false, skip_persist: true, audit_event: null, audit_detail: null
} }];

const refData = $('WF-04 Reference Data').first().json;
const sessionResult = $('WF-02 Session Store (get)').first().json;
const rawMessage = ($('Chat Trigger').first().json.chatInput || '').toString();
const sessionId = $('Chat Trigger').first().json.sessionId;

const settings = refData.settings;
const catalog = refData.catalog;

let state = sessionResult.state || {};
let stage = sessionResult.stage || 'AWAIT_CODE';
let verifiedAt = sessionResult.verified_at || null;
let verificationFresh = sessionResult.verification_fresh || false;
let timedOut = false;

if (sessionResult.expired) {
  state = {};
  stage = 'AWAIT_CODE';
  verifiedAt = null;
  verificationFresh = false;
  timedOut = true;
}

if (rawMessage.length > Number(settings.MAX_MESSAGE_CHARS || 1000)) {
  return [{ json: { blocked: true, reason: 'TOO_LONG', reply: 'That message is a bit long — could you give me the short version?', state, stage, settings, catalog, session_id: sessionId, employee_code: state.employee ? state.employee.code : '', raw_message: rawMessage, timed_out: timedOut } }];
}

if (stage === 'LOCKED' || stage === 'PIN_LOCKED') {
  const lockedUntil = state.locked_until ? new Date(state.locked_until).getTime() : 0;
  if (Date.now() < lockedUntil) {
    const lockoutMin = Math.ceil((lockedUntil - Date.now()) / 60000);
    const lockMsg = stage === 'PIN_LOCKED'
      ? `Too many incorrect attempts. Your WorkLog PIN is locked for ${lockoutMin} minutes. Nothing has been saved.`
      : 'Too many incorrect codes. Please try again in a few minutes.';
    return [{ json: { blocked: true, reason: 'LOCKED', reply: lockMsg, state, stage, settings, catalog, session_id: sessionId, employee_code: '', raw_message: rawMessage, timed_out: timedOut } }];
  }
  stage = 'AWAIT_CODE';
  state.attempts = 0;
}

const now = Date.now();
const TEN_MIN = 10 * 60 * 1000;
state.message_log = Array.isArray(state.message_log) ? state.message_log.filter(t => now - t < TEN_MIN) : [];
if (state.message_log.length > 20) {
  return [{ json: { blocked: true, reason: 'RATE_LIMITED', reply: "You're sending messages a bit fast — please wait a moment and try again.", state, stage, settings, catalog, session_id: sessionId, employee_code: state.employee ? state.employee.code : '', raw_message: rawMessage, timed_out: timedOut } }];
}
state.message_log.push(now);

return [{ json: {
  blocked: false,
  reason: null,
  state,
  stage,
  verified_at: verifiedAt,
  verification_fresh: verificationFresh,
  settings,
  catalog,
  session_id: sessionId,
  employee_code: state.employee ? state.employee.code : '',
  raw_message: rawMessage,
  timed_out: timedOut
} }];

const g = $json;
return [{ json: {
  reply: g.reply, stage: g.stage, state: g.state, session_id: g.session_id,
  employee_code: g.employee_code, timed_out: g.timed_out, skip_persist: false,
  audit_event: g.reason === 'RATE_LIMITED' ? 'RATE_LIMITED' : null,
  audit_detail: { reason: g.reason }
} }];

const guard = $('Session guard').first().json;
const identity = $json;
let state = guard.state || {};

if (identity.ok) {
  if (identity.unassigned) {
    return [{ json: {
      identity_ok: false, state, stage: 'ASSIGNED',
      reply: "You're not assigned to a project in WorkLog yet — please contact your Capability Manager.",
      session_id: guard.session_id, employee_code: identity.employee_code, timed_out: guard.timed_out,
      audit_event: 'IDENTITY_REJECTED', audit_detail: { reason: 'UNASSIGNED' }
    } }];
  }

  state.employee = identity.employee;
  state.assignment = identity.assignment;
  state.attempts = 0;
  state.pending_entry = {};
  state.expected_field = null;
  state.comment_asked = false;

  const projects = identity.assignment.projects || [];
  let reply = '';
  if (projects.length === 1) {
    state.pending_entry.project = projects[0].project;
    reply = `Welcome, ${identity.employee.name}. You're assigned to ${projects[0].project}.\nWould you like to see the activities mapped to this project?`;
    state.expected_field = 'show_activities';
  } else {
    const pNames = projects.map(p => p.project).join(', ');
    reply = `Welcome, ${identity.employee.name}. You're assigned to ${projects.length} projects: ${pNames}. Which one is this entry for?`;
    state.expected_field = 'project';
  }

  return [{ json: {
    identity_ok: true, state, stage: 'ASSIGNED',
    reply,
    session_id: guard.session_id, employee_code: identity.employee.code, timed_out: guard.timed_out
  } }];
}

state.attempts = (state.attempts || 0) + 1;
const locked = state.attempts >= 3;
if (locked) {
  state.locked_until = new Date(Date.now() + 15 * 60 * 1000).toISOString();
}

let reply = "I couldn't find that Employee Code. Please check and try again.";
if (identity.code === 'EMPLOYEE_INACTIVE') {
  reply = "Your account isn't active in WorkLog. Please contact HR.";
} else if (identity.code === 'EMPLOYEE_LOCKED' || locked) {
  reply = 'Too many incorrect codes. Please try again in a few minutes, or contact HR.';
}

return [{ json: {
  identity_ok: false, state, stage: locked ? 'LOCKED' : 'AWAIT_CODE',
  reply,
  session_id: guard.session_id, employee_code: '', timed_out: guard.timed_out,
  audit_event: 'IDENTITY_REJECTED', audit_detail: { code: identity.code }
} }];

const guard = $('Session guard').first().json;
const raw = (guard.raw_message || '').toString().trim();
const lower = raw.toLowerCase();
const state = guard.state || {};
const menu = state.shown_menu || null;

let result = null;

if (matches(/^(cancel|stop|start over)$/)) {
  result = { intent: 'cancel', entries: [], edit_field: null };
} else if (matches(/^(confirm|yes|ok|save|looks good)$/) && state.stage === 'SUMMARY' && guard.verification_fresh) {
  result = { intent: 'confirm', entries: [], edit_field: null };
} else if (matches(/^(edit|change)$/)) {
  result = { intent: 'edit', entries: [], edit_field: null };
} else if (matches(/^help$/)) {
  result = { intent: 'help', entries: [], edit_field: null };
} else if (state.expected_field === 'show_activities' && matches(/^(yes|yeah|ok|sure)$/)) {
  result = { intent: 'query_activities', entries: [], edit_field: null };
} else if (state.expected_field === 'additional_comments' && matches(/^(no|none|skip)$/)) {
  result = { intent: 'skip_comment', entries: [], edit_field: null };
} else if (menu && /^\d+$/.test(raw)) {
  const idx = parseInt(raw, 10) - 1;
  if (menu.options && menu.options[idx]) {
    const entry = { project: null, activity: null, work_date: null, hours: null, task_description: null, additional_comments: null, confidence: { project: 0, activity: 0, hours: 0, work_date: 0 } };
    entry[menu.field] = menu.options[idx];
    entry.confidence[menu.field] = 1;
    result = { intent: 'provide_field', entries: [entry], edit_field: null };
  }
} else if (matches(/which project|what am i assigned to/)) {
  result = { intent: 'query_assignment', entries: [], edit_field: null };
} else if (matches(/what activities|list activities/)) {
  result = { intent: 'query_activities', entries: [], edit_field: null };
}

function matches(re) { return re.test(lower); }

return [{ json: { matched: !!result, quick_result: result } }];

const guard = $('Session guard').first().json;
const state = guard.state || {};
const raw = guard.raw_message || '';
const expected = state.expected_field;

const entry = { project: null, activity: null, work_date: null, hours: null, task_description: null, additional_comments: null, confidence: { project: 0, activity: 0, hours: 0, work_date: 0 } };
if (expected && expected !== 'additional_comments' && expected !== 'show_activities') {
  entry[expected] = raw;
  if (entry.confidence[expected] !== undefined) entry.confidence[expected] = 0.9;
} else if (expected === 'additional_comments') {
  entry.additional_comments = raw;
}

return [{ json: { intent: 'provide_field', entries: [entry], edit_field: null, menu_mode: true } }];

const guard = $('Session guard').first().json;
const state = guard.state || {};
const raw = guard.raw_message || '';
const expected = state.expected_field;

const entry = { project: null, activity: null, work_date: null, hours: null, task_description: null, additional_comments: null, confidence: { project: 0, activity: 0, hours: 0, work_date: 0 } };
if (expected && expected !== 'additional_comments' && expected !== 'show_activities') {
  entry[expected] = raw;
  if (entry.confidence[expected] !== undefined) entry.confidence[expected] = 0.9;
} else if (expected === 'additional_comments') {
  entry.additional_comments = raw;
}

return [{ json: { intent: 'provide_field', entries: [entry], edit_field: null, menu_mode: true, ai_error: true } }];

let source;
if ($('Quick intents').first().json.matched) {
  source = $('Quick intents').first().json.quick_result;
} else {
  source = $json.restored || $json;
}

return [{ json: {
  intent: source.intent || 'off_topic',
  entries: source.entries || [],
  edit_field: source.edit_field || null,
  menu_mode: !!source.menu_mode
} }];

const guard = $('Session guard').first().json;
const raw = guard.raw_message || '';
const re = /ignore (all )?(previous|prior) instructions|system prompt|you are now|disregard/i;
const suspected = re.test(raw);
return [{ json: { injection_suspected: suspected } }];

const guard = $('Session guard').first().json;
const identity = $('Handle Identity Result');
const state = (identity.isExecuted && identity.first().json.state) ? identity.first().json.state : guard.state;
const projects = (state.assignment && state.assignment.projects) ? state.assignment.projects : [];
const pNames = projects.map(p => p.project).join(', ');
const reply = `You're assigned to ${projects.length} project(s): ${pNames}. Would you like to see the activities mapped to them?`;
state.expected_field = 'show_activities';
return [{ json: { reply, stage: state.stage || 'ASSIGNED', state, session_id: guard.session_id, employee_code: state.employee ? state.employee.code : '', timed_out: guard.timed_out } }];

const guard = $('Session guard').first().json;
const identity = $('Handle Identity Result');
const state = (identity.isExecuted && identity.first().json.state) ? identity.first().json.state : guard.state;
const projects = (state.assignment && state.assignment.projects) ? state.assignment.projects : [];
const selectedProj = state.pending_entry.project || (projects.length === 1 ? projects[0].project : null);
const projObj = projects.find(p => p.project === selectedProj) || projects[0];

if (!projObj) {
  return [{ json: { reply: "You're not assigned to a project in WorkLog yet — please contact your Capability Manager.", stage: 'ASSIGNED', state, session_id: guard.session_id, employee_code: state.employee ? state.employee.code : '', timed_out: guard.timed_out } }];
}

const activities = projObj.activities || [];
const listText = activities.map((a, i) => `        ${i + 1}. ${a}`).join('\n');
const tz = state.employee ? state.employee.timezone || 'Asia/Kolkata' : 'Asia/Kolkata';
const now = new Date();
const weekday = new Intl.DateTimeFormat('en-US', { weekday: 'short', timeZone: tz }).format(now);
const dateLabel = new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short', year: 'numeric', timeZone: tz }).format(now).replace(/ /g, ' ');

state.shown_menu = { field: 'activity', options: activities };
state.expected_field = 'activity';
state.stage = 'COLLECT';

const reply = `This project has ${activities.length} activities:\n${listText}\nWhat did you work on today (${weekday}, ${dateLabel})?`;

return [{ json: { reply, stage: 'COLLECT', state, session_id: guard.session_id, employee_code: state.employee ? state.employee.code : '', timed_out: guard.timed_out, audit_event: 'ASSIGNMENT_SHOWN', audit_detail: { project: projObj.project } } }];

const guard = $('Session guard').first().json;
const identity = $('Handle Identity Result');
const state = (identity.isExecuted && identity.first().json.state) ? identity.first().json.state : guard.state;
const settings = guard.settings;
const LOW_CONF = Number(settings.LOW_CONFIDENCE_THRESHOLD || 0.75);
const understanding = $json;

state.pending_entry = state.pending_entry || {};
state.pending_entry.confidence = state.pending_entry.confidence || {};

const entry = (understanding.entries && understanding.entries[0]) || {};
const fields = ['project', 'activity', 'work_date', 'hours', 'task_description', 'additional_comments'];

function fieldConfidence(field) {
  if (field === 'task_description' || field === 'additional_comments') return 1;
  return entry.confidence ? Number(entry.confidence[field] || 0) : 0;
}

if (understanding.intent === 'provide_field' && state.expected_field) {
  const f = state.expected_field;
  if (entry[f] !== null && entry[f] !== undefined && fieldConfidence(f) >= LOW_CONF) {
    state.pending_entry[f] = entry[f];
    state.pending_entry.confidence[f] = fieldConfidence(f);
  }
} else if (understanding.intent === 'edit_pending' && understanding.edit_field) {
  const f = understanding.edit_field;
  if (entry[f] !== null && entry[f] !== undefined) {
    state.pending_entry[f] = entry[f];
    state.pending_entry.confidence[f] = fieldConfidence(f);
  }
} else if (understanding.intent === 'skip_comment') {
  state.pending_entry.additional_comments = '';
  state.comment_asked = true;
} else {
  for (const f of fields) {
    if (entry[f] === null || entry[f] === undefined) continue;
    if (fieldConfidence(f) < LOW_CONF) continue;
    state.pending_entry[f] = entry[f];
    if (entry.confidence && entry.confidence[f] !== undefined) state.pending_entry.confidence[f] = entry.confidence[f];
  }
}

return [{ json: { state, settings, catalog: guard.catalog, session_id: guard.session_id, timed_out: guard.timed_out } }];

const merged = $('Merge into pending').first().json;
const state = merged.state;
const settings = merged.settings;
const validation = $json;

function activityMenuOptions() {
  const proj = validation.resolved.project || state.pending_entry.project;
  const projects = (state.assignment && state.assignment.projects) ? state.assignment.projects : [];
  const entry = projects.find(p => p.project === proj);
  return entry ? entry.activities : [];
}

state.pending_entry.project = validation.resolved.project || state.pending_entry.project;
state.pending_entry.activity = validation.resolved.activity || state.pending_entry.activity;

let reply, expectedField = null, menu = null, stage = 'COLLECT';

if (validation.errors && validation.errors.length) {
  const err = validation.errors[0];
  reply = err.message;
  expectedField = err.field;
  if (err.field === 'activity' && err.code === 'ACTIVITY_NOT_IN_PROJECT') {
    const options = activityMenuOptions();
    menu = { field: 'activity', options };
    state.shown_menu = menu;
    reply = `That activity isn't mapped to ${state.pending_entry.project || 'this project'}. Choose one of:\n` + options.map((a, i) => `        ${i + 1}. ${a}`).join('\n');
  }
} else if (validation.missing_fields && validation.missing_fields.length) {
  const field = validation.missing_fields[0];
  expectedField = field;
  if (field === 'project') {
    const projects = (state.assignment && state.assignment.projects) ? state.assignment.projects : [];
    const options = projects.map(p => p.project);
    menu = { field: 'project', options };
    state.shown_menu = menu;
    reply = 'Which project was this for?\n' + options.map((p, i) => `        ${i + 1}. ${p}`).join('\n');
  } else if (field === 'activity') {
    const options = activityMenuOptions();
    menu = { field: 'activity', options };
    state.shown_menu = menu;
    reply = 'Which activity was this? Reply with a number or the name.\n' + options.map((a, i) => `        ${i + 1}. ${a}`).join('\n');
  } else if (field === 'hours') {
    reply = 'How many hours did you contribute? (quarter-hour steps, e.g. 6 or 6.5)';
  } else if (field === 'task_description') {
    reply = 'Briefly, what did the work involve?';
  }
} else if (!state.comment_asked) {
  state.comment_asked = true;
  expectedField = 'additional_comments';
  reply = 'Would you like to add an additional comment? (optional — type it, or reply "no")';
} else {
  const e = validation.entry;
  const entryId = 'WL-' + $now.setZone(state.employee.timezone || 'Asia/Kolkata').toFormat('yyyyMMdd') + '-' + Math.random().toString(16).slice(2, 8).toUpperCase();
  state.entry_id = entryId;
  state.pending_entry = e;

  const warnLines = (validation.warnings || []).map(w => w.message).join('\n');
  const isFresh = $('Session guard').first().json.verification_fresh;

  const footerText = isFresh
    ? 'Reply Confirm to save, Edit to change a field, or Cancel.'
    : 'This will be your logged time for today. To confirm and sign it off, enter your WorkLog PIN. (Reply "edit" to change a field, or "cancel".)';

  reply = (warnLines ? warnLines + '\n' : '') +
    "Here's your entry — please check it:\n" +
    `        Employee Code   ${state.employee.code}\n` +
    `        Date            ${e.work_date}\n` +
    `        Project         ${e.project}\n` +
    `        Activity Type   ${e.activity}\n` +
    `        Hours           ${e.hours}\n` +
    `        Task            ${e.task_description}\n` +
    `        Comments        ${e.additional_comments || '—'}\n` +
    footerText;

  expectedField = null;
  stage = isFresh ? 'SUMMARY' : 'AWAIT_PIN';
}

state.expected_field = expectedField;

return [{ json: {
  reply,
  stage,
  state,
  session_id: merged.session_id || $('Session guard').first().json.session_id,
  employee_code: state.employee ? state.employee.code : '',
  timed_out: merged.timed_out,
  audit_event: (stage === 'SUMMARY' || stage === 'AWAIT_PIN') ? 'SUMMARY_SHOWN' : (validation.errors && validation.errors.length ? 'VALIDATION_FAILED' : null),
  audit_detail: (stage === 'SUMMARY' || stage === 'AWAIT_PIN') ? { entry_id: state.entry_id } : (validation.errors && validation.errors[0] || null)
} }];

// Stage 5: Handle PIN verification / Save execution
const guard = $('Session guard').first().json;
const state = guard.state;
const rawPin = guard.raw_message;

if (/^[a-zA-Z]+$/.test(rawPin) && rawPin !== 'cancel') {
  return [{ json: {
    reply: 'Please enter your 6-digit WorkLog PIN to sign off this entry, or reply cancel.',
    stage: 'AWAIT_PIN',
    state,
    session_id: guard.session_id,
    employee_code: guard.employee_code,
    timed_out: guard.timed_out
  } }];
}

return [{ json: {
  employee_code: state.employee ? state.employee.code : '',
  pin: rawPin,
  session_id: guard.session_id,
  settings: guard.settings
} }];

const guard = $('Session guard').first().json;
const verifyRes = $json;
const state = guard.state;

if (!verifyRes.ok) {
  let reply = 'That PIN didn\'t match. Please try again.';
  let stage = 'AWAIT_PIN';
  if (verifyRes.code === 'PIN_MISMATCH') {
    reply = `That PIN didn't match. ${verifyRes.attempts_left} attempts left.`;
  } else if (verifyRes.code === 'PIN_LOCKED') {
    reply = 'Too many incorrect attempts. Your WorkLog PIN is locked for 15 minutes. Nothing has been saved.';
    stage = 'PIN_LOCKED';
    state.pending_entry = {};
  } else if (verifyRes.code === 'PIN_NOT_SET') {
    reply = "You don't have a WorkLog PIN yet — please ask HR to set one up.";
  }
  return [{ json: { verify_ok: false, reply, stage, state, session_id: guard.session_id, employee_code: guard.employee_code, timed_out: guard.timed_out } }];
}

return [{ json: {
  verify_ok: true,
  verified_at: verifyRes.verified_at,
  state,
  session_id: guard.session_id,
  employee_code: guard.employee_code,
  settings: guard.settings
} }];

const guard = $('Session guard').first().json;
const result = $json;
const state = guard.state;

if (!result.ok) {
  return [{ json: { reply: `I couldn't confirm that the entry saved. Please check with HR before logging it again — Entry ID ${state.entry_id}.`, stage: 'SAVED', state, session_id: guard.session_id, employee_code: guard.employee_code, timed_out: guard.timed_out, audit_event: 'AI_ERROR', audit_detail: { code: result.code } } }];
}

const entry = state.pending_entry;
const verifiedAt = $('Handle PIN Result').first().json.verified_at || new Date().toISOString();
const dateLabel = entry.work_date;
const reply = `✅ Verified and saved. Entry ID ${state.entry_id} — ${entry.hours} h logged for ${dateLabel}. Total for today: ${result.day_total} h.\nAnything else to log? (yes / no)`;

const nextState = {
  employee: state.employee,
  assignment: state.assignment,
  verified_at: verifiedAt,
  pending_entry: {},
  expected_field: null,
  comment_asked: false,
  entry_id: null,
  attempts: 0,
  message_log: state.message_log
};

return [{ json: { reply, stage: 'SAVED', state: nextState, verified_at: verifiedAt, session_id: guard.session_id, employee_code: guard.employee_code, timed_out: guard.timed_out, audit_event: 'CONFIRMED', audit_detail: { entry_id: state.entry_id } } }];

const guard = $('Session guard').first().json;
const state = guard.state;
state.pending_entry = {};
state.expected_field = null;
state.comment_asked = false;
state.entry_id = null;
return [{ json: { reply: 'Cancelled. Nothing was saved. Anything else to log?', stage: 'ASSIGNED', state, session_id: guard.session_id, employee_code: guard.employee_code, timed_out: guard.timed_out, audit_event: 'CANCELLED', audit_detail: null } }];

const guard = $('Session guard').first().json;
const state = guard.state;
state.expected_field = null;
return [{ json: { reply: 'Which field — activity, hours, task or comments?', stage: 'COLLECT', state, session_id: guard.session_id, employee_code: guard.employee_code, timed_out: guard.timed_out, audit_event: null, audit_detail: null } }];

const guard = $('Session guard').first().json;
const tz = guard.state.employee.timezone || 'Asia/Kolkata';
const today = $now.setZone(tz).toFormat('yyyy-MM-dd');
const weekStart = $now.setZone(tz).minus({ days: 6 }).toFormat('yyyy-MM-dd');

const rows = $input.all().map(i => i.json).filter(r => (r.Status || 'LOGGED') !== 'SUPERSEDED');
const todayTotal = rows.filter(r => (r.Date || '').toString().slice(0, 10) === today).reduce((s, r) => s + (Number(r['Contributed Hours']) || 0), 0);
const weekTotal = rows.filter(r => (r.Date || '').toString().slice(0, 10) >= weekStart).reduce((s, r) => s + (Number(r['Contributed Hours']) || 0), 0);

return [{ json: { reply: `You've logged ${todayTotal} h today and ${weekTotal} h this week.`, stage: guard.stage, state: guard.state, session_id: guard.session_id, employee_code: guard.employee_code, timed_out: guard.timed_out, audit_event: null, audit_detail: null } }];

const guard = $('Session guard').first().json;
const reply = 'I can help you log your work hours. Tell me what you worked on, the activity, hours and date — e.g. "6 hours today for Client Communication". You can also say Cancel, Edit, or ask about your logged hours.';
return [{ json: { reply, stage: guard.stage, state: guard.state, session_id: guard.session_id, employee_code: guard.employee_code, timed_out: guard.timed_out, audit_event: null, audit_detail: null } }];

const input = $input.first().json;
let reply = input.reply || '';
if (input.timed_out) {
  reply = 'Your previous session timed out, so let\'s start fresh. ' + reply;
}

return [{ json: {
  output: reply,
  stage: input.stage,
  state: input.state,
  verified_at: input.verified_at,
  session_id: input.session_id,
  employee_code: input.employee_code,
  audit_event: input.audit_event,
  audit_detail: input.audit_detail,
  skip_persist: !!input.skip_persist
} }];

// Adapter: reconstructs the workflowInputs shape the sub-workflow's trigger used to receive.
return [{ json: {
  "force_refresh": (false)
} }];

const staticData = $getWorkflowStaticData('global');
const forceRefresh = !!($input.first().json.force_refresh);
const now = Date.now();
const FIVE_MIN = 5 * 60 * 1000;

const cacheValid = !forceRefresh
  && staticData.referenceDataCache
  && (now - staticData.referenceDataCache.fetchedAtMs) < FIVE_MIN;

return [{ json: { cacheValid, cached: cacheValid ? staticData.referenceDataCache.payload : null } }];

const DEFAULTS = {
  AI_ENABLED: true,
  MAX_HOURS_PER_DAY: 16,
  MAX_HOURS_PER_ENTRY: 12,
  HOURS_STEP: 0.25,
  BACKDATE_DAYS: 7,
  WORKING_DAYS: [1, 2, 3, 4, 5],
  DEFAULT_TIMEZONE: 'Asia/Kolkata',
  SESSION_TIMEOUT_MIN: 30,
  PIN_LENGTH: 6,
  PIN_MAX_ATTEMPTS: 3,
