const crypto = require('crypto');
const input = $input.first().json;
const codeRaw = (input['Employee Code'] || input.employee_code || '').toString();
const pinRaw = (input['New PIN (6 digits)'] || input.new_pin || '').toString().trim();
const confirmRaw = (input['Confirm PIN'] || input.confirm_pin || '').toString().trim();

const employeeCode = codeRaw.trim().toUpperCase().replace(/\s+/g, '');

if (!employeeCode) {
  return [{ json: { ok: false, message: 'Employee Code is required.' } }];
}

if (pinRaw !== confirmRaw) {
  return [{ json: { ok: false, message: 'New PIN and Confirm PIN do not match.' } }];
}

if (!/^\d{6}$/.test(pinRaw)) {
  return [{ json: { ok: false, message: 'PIN must be exactly 6 digits.' } }];
}

// Reject weak PINs: all same digit, sequential, or contains employee code digits
if (/^(\d)\1{5}$/.test(pinRaw) || pinRaw === '123456' || pinRaw === '654321') {
  return [{ json: { ok: false, message: 'That PIN is too easy to guess. Please choose a different 6-digit PIN.' } }];
}

const codeDigits = employeeCode.replace(/\D/g, '');
if (codeDigits.length >= 4 && pinRaw.includes(codeDigits)) {
  return [{ json: { ok: false, message: 'PIN must not contain your Employee Code digits.' } }];
}

const pepper = process.env.APP_PIN_PEPPER || $vars.WORKLOG_PEPPER || 'default_worklog_pepper_secret_hex';
const pinHash = crypto.createHmac('sha256', pepper).update(pinRaw).digest('hex');

return [{
  json: {
    ok: true,
    employee_code: employeeCode,
    pin_hash: pinHash,
    set_at: new Date().toISOString()
  }
}];

